function css(){if(document.getElementById('fpon-0902-css'))return;const s=document.createElement('style');s.id='fpon-0902-css';s.textContent=`#fpon-daily-quote{margin:10px 0 2px;padding:12px 16px;border-radius:14px;background:linear-gradient(135deg,#f6f9ff,#fffaf3);border:1px solid #e4e9f1;max-width:680px}#fpon-daily-quote .quote-label{font-size:11px;font-weight:900;color:#7a5a18;margin-bottom:5px}#fpon-daily-quote .quote-text{font-size:17px;line-height:1.55;font-weight:800;color:#243c5a}.issue-feature{padding:18px 20px!important;border-radius:16px!important;background:linear-gradient(135deg,#f7fbff,#fff)!important;border:1px solid #dfe9f5!important}.issue-feature+.issue-feature{margin-top:10px}.issue-label{display:inline-flex;padding:5px 10px;border-radius:999px;font-size:12px;font-weight:900;margin-bottom:9px}.issue-label.season{background:#e8f4ff;color:#1764a5}.issue-label.day{background:#fff0f4;color:#a53b62}.issue-label.important{background:#fff6df;color:#8a6416}.issue-main{font-size:21px;line-height:1.45;font-weight:950;color:#193a61;margin-bottom:9px}.issue-detail{font-size:14px;line-height:1.75;color:#526477}.news4{grid-template-columns:repeat(2,1fr)!important;gap:12px!important}.news4 .news{min-height:176px!important;cursor:pointer;position:relative;padding:15px 120px 40px 16px!important;overflow:hidden}.news4 .news:after{content:'자세히 보기 ›';position:absolute;left:16px;bottom:14px;font-size:11px;font-weight:900;color:#245b9e}.news-kicker{display:inline-flex!important;padding:5px 10px!important;border-radius:999px!important;font-size:12px!important;font-weight:950!important;background:#eaf3ff!important;color:#195e9f!important;margin-bottom:10px!important}.news-thumb{position:absolute;right:0;top:0;width:108px;height:100%;display:flex;align-items:center;justify-content:center;font-size:46px;background:linear-gradient(145deg,#eef5fc,#dfeaf6);border-left:1px solid #e3eaf1}.news-modal-bg{position:fixed;inset:0;background:rgba(17,31,49,.52);z-index:99999;display:flex;align-items:center;justify-content:center;padding:18px}.news-modal{width:min(640px,100%);max-height:82vh;overflow:auto;background:#fff;border-radius:20px;padding:24px}.news-modal-visual{height:160px;border-radius:15px;background:linear-gradient(135deg,#edf5fd,#dceaf7);display:flex;align-items:center;justify-content:center;font-size:76px;margin-bottom:18px}.news-modal-close{float:right;border:0;background:#eef3f8;border-radius:50%;width:36px;height:36px;font-size:20px}.econ .m{display:grid!important;grid-template-columns:minmax(110px,.7fr) minmax(165px,1.3fr);gap:10px;align-items:center}.metric-week{border-left:1px solid #e7edf3;padding-left:10px}.econ-chart{width:100%;height:72px;display:block}.econ-chart .line{fill:none;stroke:#2f6fb0;stroke-width:2.2}.econ-chart .dot{fill:#fff;stroke:#2f6fb0;stroke-width:1.5}.econ-chart text{font-size:8px;fill:#6f7c8b}.econ-values{display:grid;grid-template-columns:repeat(5,1fr);gap:3px;margin-top:3px}.econ-values div{font-size:8.5px;text-align:center;color:#526477;background:#f5f8fb;border-radius:5px;padding:3px 1px}.variable-wait{padding:20px;border:1px solid #dce6f0;border-radius:16px;background:#f8fbff}.variable-wait b{color:#1f5f9d}@media(max-width:800px){.news4{grid-template-columns:1fr!important}.econ .m{grid-template-columns:1fr}.metric-week{border-left:0;border-top:1px solid #e7edf3;padding:8px 0 0}.issue-main{font-size:19px}}`;document.head.appendChild(s)}
