function issues(){const box=document.querySelector('.issues');if(!box)return;box.innerHTML=`<div class="issue issue-feature"><span class="issue-label season">🌾 24절기</span><div class="issue-main">지금은 ‘처서’와 ‘백로’ 사이입니다.</div><div class="issue-detail"><b>처서</b>는 더위가 물러나기 시작하는 때, <b>백로</b>는 이슬이 맺히며 초가을 기운이 짙어지는 절기입니다. 다음 절기 백로는 9월 초 찾아옵니다.</div></div><div class="issue issue-feature"><span class="issue-label day">🥥 오늘은 무슨 날?</span><div class="issue-main">9월 2일은 ‘세계 코코넛의 날’입니다.</div><div class="issue-detail">코코넛의 경제·환경적 가치와 생산 농가의 삶을 알리기 위해 매년 9월 2일 기념합니다. 한국에서는 오늘 9월 모의평가 일정도 진행됩니다.</div></div><div class="issue issue-feature"><span class="issue-label important">📌 오늘의 핵심 이슈</span><div class="issue-main">정기국회 본격화 · 네팔 대홍수 수색 · 금융시장 변동성</div><div class="issue-detail">국내에서는 정기국회 심사가 본격화되고, 해외에서는 네팔 대홍수 실종자 수색이 이어지고 있습니다. 금융시장은 유가·환율 움직임을 함께 살펴볼 필요가 있습니다.</div></div>`;const issueSec=box.closest('section')||box.parentElement,health=document.querySelector('.health-meal');if(issueSec&&health&&issueSec.parentNode===health.parentNode)issueSec.insertAdjacentElement('afterend',health)}
function modal(item){const bg=document.createElement('div');bg.className='news-modal-bg';bg.innerHTML=`<div class="news-modal"><button class="news-modal-close">×</button><div class="news-modal-visual">${item[3]}</div><span class="news-kicker">${item[0]}</span><h3>${item[1]}</h3><p>${item[2]}</p><div style="margin-top:14px;padding:12px;border-radius:12px;background:#f5f8fc;font-size:12px;color:#5d6f82">기준/출처: ${item[4]}</div></div>`;document.body.appendChild(bg);bg.querySelector('button').onclick=()=>bg.remove();bg.onclick=e=>{if(e.target===bg)bg.remove()}}
function news(){const sec=[...document.querySelectorAll('section')].find(x=>x.querySelector('h2')&&x.querySelector('h2').textContent.includes('오늘의 뉴스'));if(!sec)return;let grid=sec.querySelector('.news4');if(!grid){grid=document.createElement('div');grid.className='news4';sec.appendChild(grid)}grid.innerHTML=NEWS.map((x,i)=>`<div class="news" data-news="${i}"><span class="news-kicker">${x[0]}</span><b>${x[1]}</b><span>${x[2]}</span><div class="news-thumb">${x[3]}</div></div>`).join('');grid.querySelectorAll('[data-news]').forEach(el=>el.onclick=()=>modal(NEWS[+el.dataset.news]))}
function svg(o){const w=220,h=72,p={l:5,r:6,t:12,b:17},min=Math.min(...o.values),max=Math.max(...o.values),range=(max-min)||1,pts=o.values.map((v,i)=>({x:p.l+i*(w-p.l-p.r)/(o.values.length-1),y:p.t+(max-v)/range*(h-p.t-p.b),v,label:o.labels[i]}));return `<svg class="econ-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline class="line" points="${pts.map(q=>q.x+','+q.y).join(' ')}"/>${pts.map(q=>`<circle class="dot" cx="${q.x}" cy="${q.y}" r="2.4"/><text x="${q.x}" y="${h-4}" text-anchor="middle">${q.label}</text>`).join('')}</svg><div class="econ-values">${pts.map(q=>`<div>${q.v.toLocaleString('ko-KR',{maximumFractionDigits:2})}</div>`).join('')}</div>`}
function econAttach(container,map){if(!container)return;[...container.querySelectorAll('.m')].forEach(m=>{m.querySelectorAll('.metric-week').forEach(x=>x.remove());const n=(m.querySelector('.mn')?.textContent||'');const key=map.find(x=>n.includes(x[0]))?.[1];if(!key)return;const wk=document.createElement('div');wk.className='metric-week';wk.innerHTML=`<div style="font-size:10px;font-weight:900;color:#64778d">최근 1주일 비교 · 9/1 마감 기준</div>${svg(ECON[key])}`;m.appendChild(wk);const mv=m.querySelector('.mv');if(mv)mv.textContent=ECON[key].values.at(-1).toLocaleString('ko-KR',{maximumFractionDigits:2})})}
